        from itertools import combinations

def verifier(assign):
    M = assign['M']
    if M < 4:
        # M=2 gives one vector (1,1), sum 2. 
        # M=3 gives {(1,1),(1,2),(2,1)}, no conflicts, sum 8.
        # These are too trivial for the problem's structure.
        return False, None

    vectors_map = {}
    for norm in range(2, M + 1):
        for x in range(1, norm):
            y = norm - x
            vectors_map[(x, y)] = norm

    vectors = sorted(vectors_map.keys())
    total_norm = sum(vectors_map.values())

    # Find minimal circuits (minimal subsets with a sum-to-zero conflict)
    circuits = []
    for k in range(4, len(vectors) + 1):
        for sub_indices in combinations(range(len(vectors)), k):

            is_superset = False
            for c_indices in circuits:
                if set(c_indices).issubset(set(sub_indices)):
                    is_superset = True
                    break
            if is_superset:
                continue

            # Iterate through partitions of the subset into two non-empty sets A and B
            for i in range(1, 1 << (k - 1)):
                sum_A = [0, 0]
                sum_B = [0, 0]

                for j in range(k):
                    v = vectors[sub_indices[j]]
                    if (i >> j) & 1:
                        sum_A[0] += v[0]
                        sum_A[1] += v[1]
                    else:
                        sum_B[0] += v[0]
                        sum_B[1] += v[1]

                if sum_A[0] == sum_B[0] and sum_A[1] == sum_B[1]:
                    circuits.append(sub_indices)
                    break

    if not circuits:
        return True, total_norm

    # Solve minimum weight hitting set by brute force over the set of removed vectors
    min_loss = float('inf')
    num_vectors = len(vectors)

    for i in range(1, 1 << num_vectors):
        removed_indices = set()
        current_loss = 0
        for j in range(num_vectors):
            if (i >> j) & 1:
                removed_indices.add(j)
                current_loss += vectors_map[vectors[j]]

        if current_loss >= min_loss:
            continue

        is_hitting_set = True
        for c_indices in circuits:
            if not any(idx in removed_indices for idx in c_indices):
                is_hitting_set = False
                break

        if is_hitting_set:
            min_loss = current_loss

    answer = total_norm - min_loss
    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
